// n8n · workflow LANOPS-PEGAR-OFERTA · nodo "Code: entrada"
// Modo: Run Once for All Items · JavaScript
// Recibe el formulario de lanops/pegar-oferta/index.html (POST urlencoded en $json.body).
// Identifica al usuario con su enlace firmado de ENCAJE: u y t, o el enlace entero pegado en "enlace".
// firma = HMAC-SHA256(ENCAJE_SECRET, 'encaje:' + u), el mismo cálculo que LANOPS-ENCAJE/code-firma.js.
function sha256(bytes) {
  const K = [0x428a2f98,0x71374491,0xb5c0fbcf,0xe9b5dba5,0x3956c25b,0x59f111f1,0x923f82a4,0xab1c5ed5,
    0xd807aa98,0x12835b01,0x243185be,0x550c7dc3,0x72be5d74,0x80deb1fe,0x9bdc06a7,0xc19bf174,
    0xe49b69c1,0xefbe4786,0x0fc19dc6,0x240ca1cc,0x2de92c6f,0x4a7484aa,0x5cb0a9dc,0x76f988da,
    0x983e5152,0xa831c66d,0xb00327c8,0xbf597fc7,0xc6e00bf3,0xd5a79147,0x06ca6351,0x14292967,
    0x27b70a85,0x2e1b2138,0x4d2c6dfc,0x53380d13,0x650a7354,0x766a0abb,0x81c2c92e,0x92722c85,
    0xa2bfe8a1,0xa81a664b,0xc24b8b70,0xc76c51a3,0xd192e819,0xd6990624,0xf40e3585,0x106aa070,
    0x19a4c116,0x1e376c08,0x2748774c,0x34b0bcb5,0x391c0cb3,0x4ed8aa4a,0x5b9cca4f,0x682e6ff3,
    0x748f82ee,0x78a5636f,0x84c87814,0x8cc70208,0x90befffa,0xa4506ceb,0xbef9a3f7,0xc67178f2];
  const H = [0x6a09e667,0xbb67ae85,0x3c6ef372,0xa54ff53a,0x510e527f,0x9b05688c,0x1f83d9ab,0x5be0cd19];
  const l = bytes.length, n = ((l + 9 + 63) >> 6) << 6, m = new Uint8Array(n);
  m.set(bytes); m[l] = 0x80;
  const bits = l * 8;
  m[n - 4] = (bits >>> 24) & 255; m[n - 3] = (bits >>> 16) & 255; m[n - 2] = (bits >>> 8) & 255; m[n - 1] = bits & 255;
  m[n - 5] = Math.floor(bits / 2 ** 32) & 255;
  const w = new Uint32Array(64), r = (x, s) => (x >>> s) | (x << (32 - s));
  for (let i = 0; i < n; i += 64) {
    for (let t = 0; t < 16; t++) w[t] = (m[i+4*t] << 24) | (m[i+4*t+1] << 16) | (m[i+4*t+2] << 8) | m[i+4*t+3];
    for (let t = 16; t < 64; t++) {
      const s0 = r(w[t-15], 7) ^ r(w[t-15], 18) ^ (w[t-15] >>> 3);
      const s1 = r(w[t-2], 17) ^ r(w[t-2], 19) ^ (w[t-2] >>> 10);
      w[t] = (w[t-16] + s0 + w[t-7] + s1) | 0;
    }
    let [a, b, c, d, e, f, g, h] = H;
    for (let t = 0; t < 64; t++) {
      const t1 = (h + (r(e, 6) ^ r(e, 11) ^ r(e, 25)) + ((e & f) ^ (~e & g)) + K[t] + w[t]) | 0;
      const t2 = ((r(a, 2) ^ r(a, 13) ^ r(a, 22)) + ((a & b) ^ (a & c) ^ (b & c))) | 0;
      h = g; g = f; f = e; e = (d + t1) | 0; d = c; c = b; b = a; a = (t1 + t2) | 0;
    }
    H[0] = (H[0] + a) | 0; H[1] = (H[1] + b) | 0; H[2] = (H[2] + c) | 0; H[3] = (H[3] + d) | 0;
    H[4] = (H[4] + e) | 0; H[5] = (H[5] + f) | 0; H[6] = (H[6] + g) | 0; H[7] = (H[7] + h) | 0;
  }
  const out = new Uint8Array(32);
  H.forEach((v, i) => { out[4*i] = v >>> 24; out[4*i+1] = (v >>> 16) & 255; out[4*i+2] = (v >>> 8) & 255; out[4*i+3] = v & 255; });
  return out;
}
const utf8 = (s) => new TextEncoder().encode(s);
function hmacHex(secreto, mensaje) {
  let k = utf8(secreto);
  if (k.length > 64) k = sha256(k);
  const ki = new Uint8Array(64), ko = new Uint8Array(64);
  for (let i = 0; i < 64; i++) { ki[i] = (k[i] || 0) ^ 0x36; ko[i] = (k[i] || 0) ^ 0x5c; }
  const m = utf8(mensaje), interior = new Uint8Array(64 + m.length);
  interior.set(ki); interior.set(m, 64);
  const ih = sha256(interior), exterior = new Uint8Array(96);
  exterior.set(ko); exterior.set(ih, 64);
  return Array.from(sha256(exterior), (x) => x.toString(16).padStart(2, '0')).join('');
}

const b = $input.first().json.body || {};
let u = String(b.u || '').trim(), t = String(b.t || '').trim();
if ((!u || !t) && b.enlace) {
  // [10-oct] Con expresiones regulares: en el Code de n8n no existe URL (new URL fallaba en silencio)
  const enlace = String(b.enlace).trim();
  u = (enlace.match(/[?&]u=(\d{1,9})(?:&|$)/) || [])[1] || '';
  t = (enlace.match(/[?&]t=([0-9a-fA-F]{64})(?:&|$)/) || [])[1] || '';
}
const secreto = $env.ENCAJE_SECRET;
if (!secreto) throw new Error('Falta la variable ENCAJE_SECRET en el servicio n8n');
const valido = /^\d{1,9}$/.test(u) && /^[0-9a-f]{64}$/i.test(t) && t.toLowerCase() === hmacHex(secreto, 'encaje:' + u);
const texto = String(b.texto || '').trim().slice(0, 15000);
const motivo = !valido ? 'enlace' : texto.length < 200 ? 'texto' : null;
const url = /^https?:\/\//i.test(String(b.url || '').trim()) ? String(b.url).trim().slice(0, 255) : null;

return [{ json: {
  valido: !motivo, motivo,
  usuario: valido ? Number(u) : null, t: valido ? t.toLowerCase() : null,
  texto, empresa_form: String(b.empresa || '').trim().slice(0, 100), url
} }];

// n8n · workflow LANOPS-PEGAR-OFERTA · nodo "Code: petición extraer"
// Modo: Run Once for All Items · JavaScript
// Llamada 1 a Claude: convertir el texto pegado en los campos de VACANTES.
const ctx = $input.first().json;                       // "Postgres: contexto"
if (!ctx.usuario) throw new Error('PEGAR-OFERTA: el usuario no existe');
if (!ctx.cv_texto) throw new Error('PEGAR-OFERTA: el usuario no tiene CV (cv_texto vacío)');
const e = $('Code: entrada').first().json;
const SYSTEM = `Eres el módulo "pegar una oferta" de LANOPS. Recibes el texto de una oferta de empleo copiado de cualquier sitio.
Devuelve SOLO un JSON con esta forma:
{"puesto":"", "empresa":"", "ubicacion":"", "contrato":"indefinido|temporal|practicas|otro|", "jornada":"completa|parcial|", "salario_min":0, "descripcion":""}
Reglas:
- No inventes nada. Si un dato no está, deja "" (o 0 en salario_min).
- puesto: el título del puesto, máximo 150 caracteres.
- empresa: el nombre de la empresa que contrata (no el portal). Si es una ETT, el nombre de la ETT.
- ubicacion: municipio, máximo 60 caracteres.
- salario_min: salario bruto anual mínimo en euros, entero. Si viene mensual, multiplícalo por 14 solo si el texto dice 14 pagas; si no, por 12.
- descripcion: el texto de la oferta limpio (funciones, requisitos, condiciones), sin publicidad del portal ni avisos de cookies, máximo 6000 caracteres.`;
return [{ json: { cuerpo: {
  model: ctx.modelo || 'claude-sonnet-5-5',
  max_tokens: 8000,
  system: SYSTEM,
  messages: [{ role: 'user', content: (e.empresa_form ? 'Empresa (indicada por el usuario): ' + e.empresa_form + '\n\n' : '') + 'Oferta:\n\n' + e.texto }]
} } }];

// n8n · workflow LANOPS-PEGAR-OFERTA · nodo "Code: vacante"
// Modo: Run Once for All Items · JavaScript
// Lee el JSON de la llamada 1 y prepara la fila de VACANTES (fuente 'usuario').
// [12-oct] Añade texto_pegado (para la huella) y usuario, hash_cv y evaluador
// (para que "Postgres: guardar vacante" diga si este usuario ya tiene evaluada la oferta).
const texto = ($input.first().json.content || []).filter(b => b.type === 'text').map(b => b.text).join('');
const a = texto.indexOf('{'), z = texto.lastIndexOf('}');
if (a < 0 || z < a) throw new Error('PEGAR-OFERTA: Claude no ha devuelto JSON. Respuesta: ' + texto.slice(0, 300));
const o = JSON.parse(texto.slice(a, z + 1));
const e = $('Code: entrada').first().json;
const ctx = $('Postgres: contexto').first().json;
const txt = (v, n) => String(v ?? '').trim().slice(0, n);
const contrato = ['indefinido', 'temporal', 'practicas', 'otro'].includes(o.contrato) ? o.contrato : null;
const jornada = ['completa', 'parcial'].includes(o.jornada) ? o.jornada : null;
const salario = parseInt(o.salario_min, 10);
const puesto = txt(o.puesto, 150) || 'Puesto sin título';
return [{ json: { datos: {
  puesto,
  empresa: txt(e.empresa_form || o.empresa, 100) || 'Empresa no indicada',
  ubicacion: txt(o.ubicacion, 60) || null,
  contrato, jornada,
  salario_min: salario > 0 ? salario : null,
  requisitos: txt(o.descripcion, 6000) || e.texto.slice(0, 6000),
  url_origen: e.url,
  texto_pegado: String(e.texto || '').slice(0, 20000),
  usuario: ctx.usuario,
  hash_cv: ctx.hash_cv,
  evaluador: ctx.evaluador
} } }];

// n8n · workflow LANOPS-PEGAR-OFERTA · nodo "Code: petición evaluar"
// Modo: Run Once for All Items · JavaScript
// Llamada 2 a Claude: evaluar la vacante con el MISMO evaluador y formato que LANOPS-ENCAJE
// (code-preparar.js de ENCAJE, para una sola vacante). El prompt de career-ops sale de EVALUADORES.
const ctx = $('Postgres: contexto').first().json;
if (!ctx.prompt || !ctx.modelo) throw new Error('PEGAR-OFERTA: no hay evaluador IA activo con prompt y modelo');
const v = $input.first().json;                         // "Postgres: guardar vacante"
const prefs = ctx.preferencias || [];
const lineaPref = (p) => `- ${p.tipo} · ${p.clave} = ${p.valor}${p.tipo === 'peso' && p.peso ? ` (peso ${p.peso})` : ''}`;
const perfil = `<perfil>\n${ctx.cv_texto}\n</perfil>\n\n<preferencias>\n${prefs.map(lineaPref).join('\n') || '(sin preferencias)'}\n</preferencias>`;
// [12-oct] La fecha va en el bloque de la vacante (no en el prompt ni en el perfil): no cambia version_rubrica ni rompe la caché.
const HOY = new Intl.DateTimeFormat('sv-SE', { timeZone: 'Europe/Madrid' }).format(new Date());   // [12-oct] AAAA-MM-DD, hora de Madrid
const fmt = (k, x) => (x === null || x === undefined || x === '' ? `${k}: no consta` : `${k}: ${x}`);
return [{ json: {
  usuario: ctx.usuario, vacante: v.vacante, evaluador: ctx.evaluador, hash_cv: ctx.hash_cv,
  cuerpo: {
    model: ctx.modelo,
    max_tokens: 4096,
    system: [{ type: 'text', text: ctx.prompt, cache_control: { type: 'ephemeral' } }],
    messages: [{ role: 'user', content: [
      { type: 'text', text: perfil },
      { type: 'text', text: [
        `Fecha de hoy: ${HOY}`,
        '<vacante>',
        fmt('Puesto', v.puesto), fmt('Empresa', v.empresa_nombre), fmt('Ubicación', v.ubicacion),
        fmt('Contrato', v.contrato), fmt('Jornada', v.jornada),
        fmt('Salario mínimo anual', v.salario_min ? `${v.salario_min} €` : null),
        'Descripción:', v.requisitos || 'no consta',
        '</vacante>',
      ].join('\n') },
    ]}],
  },
} }];

// n8n · workflow LANOPS-PEGAR-OFERTA · nodo "Code: leer evaluación"
// Modo: Run Once for All Items · JavaScript
// Igual que LANOPS-ENCAJE/code-leer.js para una sola respuesta: valida d1–d5 y global,
// calcula global_personal con los pesos del usuario y la banda con los umbrales de CONFIGURACION.
const ctx = $('Postgres: contexto').first().json;
const pedida = $('Code: petición evaluar').first().json;
const alta  = Number(ctx.umbral_alta  ?? 4);
const media = Number(ctx.umbral_media ?? 3);
const MAPA = {
  d1_match_cv:     ['euskera', 'idioma'],
  d2_north_star:   ['puesto_objetivo', 'sector', 'situacion_actual'],
  d3_compensacion: ['salario_min'],
  d4_cultura:      ['estabilidad', 'modalidad', 'tamano', 'turnos', 'jornada', 'contrato',
                    'municipio', 'radio_km', 'movilidad', 'fecha_inicio_max'],
  d5_red_flags:    ['ett', 'empresa', 'palabra', 'permiso_trabajo'],
};
const pesos = (ctx.preferencias || []).filter(p => p.tipo === 'peso' && p.peso);
const pesoDim = Object.fromEntries(Object.entries(MAPA).map(([d, claves]) => {
  const ws = pesos.filter(p => claves.includes(p.clave)).map(p => Number(p.peso));
  return [d, ws.length ? Math.max(...ws) : 3];
}));
const DIM = Object.keys(MAPA);
const entero15 = (x) => Number.isInteger(x) && x >= 1 && x <= 5;

const texto = ($input.first().json.content || []).filter(b => b.type === 'text').map(b => b.text).join('').trim();
const limpio = texto.replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/, '');
const r = JSON.parse(limpio.slice(limpio.indexOf('{'), limpio.lastIndexOf('}') + 1));
for (const d of DIM) if (!entero15(r[d])) throw new Error(`PEGAR-OFERTA: ${d} fuera de 1–5: ${r[d]}`);
const g = Number(r.global);
if (!(g >= 1 && g <= 5)) throw new Error(`PEGAR-OFERTA: global fuera de 1–5: ${r.global}`);
const sumW = DIM.reduce((s, d) => s + pesoDim[d], 0);
const gp = DIM.reduce((s, d) => s + r[d] * pesoDim[d], 0) / sumW;
return [{ json: {
  usuario: pedida.usuario, vacante: pedida.vacante, evaluador: pedida.evaluador, hash_cv: pedida.hash_cv, ok: true,
  d1_match_cv: r.d1_match_cv, d2_north_star: r.d2_north_star, d3_compensacion: r.d3_compensacion,
  d4_cultura: r.d4_cultura, d5_red_flags: r.d5_red_flags,
  global: Math.round(g * 10) / 10,
  global_personal: Math.round(gp * 10) / 10,
  banda: g >= alta ? 'Alta' : g >= media ? 'Media' : 'Baja',
  explicacion: String(r.explicacion || '').slice(0, 2000),
  hueco: String(r.hueco || '').slice(0, 1000)
} }];

// n8n · workflow LANOPS-PEGAR-OFERTA · nodo "Code: HTML"
// Modo: Run Once for All Items · JavaScript
// Página con el resultado de la oferta pegada, con la misma tarjeta que LANOPS-ENCAJE/code-html.js
// (estilo común, % = global × 20, banda con texto, 5 dimensiones). "Pedir certificado" solo con banda Alta o Media.
const N8N = 'https://n8n-production-3c20b.up.railway.app/webhook';
const r = $input.first().json;                          // "Postgres: guardar evaluación"
const v = $('Postgres: guardar vacante').first().json;
const e = $('Code: entrada').first().json;
const esc = (s) => String(s ?? '').replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const nota = (g) => Number(g).toFixed(1).replace('.', ',');
const pct = (g) => Math.round(Number(g) * 20);
const BANDA = { Alta: 'alto', Media: 'medio', Baja: 'bajo' };
const DIM = [['d1_match_cv', 'Encaje con tu CV'], ['d2_north_star', 'Lo que buscas'],
             ['d3_compensacion', 'Salario'], ['d4_cultura', 'Empresa y condiciones'], ['d5_red_flags', 'Alertas (5 = ninguna)']];
const firma = `u=${e.usuario}&amp;t=${e.t}`;
const pedir = (r.banda === 'Alta' || r.banda === 'Media')
  ? `<p><a class="boton" href="${N8N}/certificar?${firma}&amp;v=${r.vacante}">Pedir certificado de esta vacante</a></p>`
  : `<p class="meta">Certificado disponible solo con encaje alto o medio.</p>`;

const html = `<!doctype html><html lang="es"><head><meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1"><meta name="robots" content="noindex">
<title>Tu encaje con esta oferta · LANOPS</title>
<link rel="stylesheet" href="https://lanopsdmm.github.io/lanops/styles.css"></head><body>
<header><p class="marca">LANOPS</p></header>
<main>
<h1>Tu encaje con esta oferta</h1>
${r.ya_evaluada ? '<p class="aviso">Ya habías pegado esta oferta: te enseñamos la evaluación que hicimos entonces.</p>' : ''}
<article class="vac">
  <h2>${esc(v.puesto)}</h2>
  <p class="meta">${esc(v.empresa_nombre)} · ${esc(v.ubicacion || 'ubicación no consta')}</p>
  <div class="barra" aria-hidden="true"><span style="width:${Math.min(100, Math.max(0, pct(r.global)))}%"></span></div>
  <p class="nota"><strong>${pct(r.global)} % · ${nota(r.global)}/5</strong> <span class="banda banda-${BANDA[r.banda] || 'bajo'}">encaje ${BANDA[r.banda] || esc(r.banda)}</span></p>
  <ul class="dims">${DIM.map(([k, t]) => `<li>${t}: <strong>${r[k]}/5</strong></li>`).join('')}</ul>
  <p>${esc(r.explicacion).replace(/\n/g, '<br>')}</p>
  ${r.hueco ? `<p><strong>Para subir un punto:</strong> ${esc(r.hueco)}</p>` : ''}
  ${v.url_origen ? `<p><a href="${esc(v.url_origen)}" rel="noopener">Ver la oferta original</a></p>` : ''}
  ${pedir}
</article>
<p><a href="${N8N}/encaje?${firma}">Ver todas mis ofertas</a> · <a href="https://lanopsdmm.github.io/lanops/pegar-oferta/?${firma}">Pegar otra oferta</a></p>
</main>
<footer><p>% de congruencia = puntuación global × 20. La IA evalúa; tú decides. Rúbrica abierta de <a href="https://github.com/career-ops-hq/career-ops">career-ops</a> (MIT).</p></footer>
</body></html>`;
return [{ json: { html } }];

// n8n · workflow LANOPS-PEGAR-OFERTA · nodo "Code: página de error"
// Modo: Run Once for All Items · JavaScript
// Rama "false" de "IF entrada válida": enlace personal no válido o texto demasiado corto.
const m = $input.first().json.motivo;
const msg = m === 'texto'
  ? 'El texto de la oferta es demasiado corto. Pega la oferta completa (puesto, requisitos, condiciones).'
  : 'No reconocemos tu enlace personal. Copia el enlace completo de "Ver mis ofertas" que te dimos al crear tu perfil.';
const html = `<!doctype html><html lang="es"><head><meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1"><meta name="robots" content="noindex">
<title>No se ha podido evaluar · LANOPS</title>
<link rel="stylesheet" href="https://lanopsdmm.github.io/lanops/styles.css"></head><body>
<header><p class="marca">LANOPS</p></header>
<main><h1>No se ha podido evaluar la oferta</h1>
<p class="aviso">${msg}</p>
<p><a href="https://lanopsdmm.github.io/lanops/pegar-oferta/">Volver a intentarlo</a> · <a href="https://lanopsdmm.github.io/lanops/alta/">Crear mi perfil</a></p>
</main></body></html>`;
return [{ json: { html } }];
